function disposeItem(g){g.parent?.remove(g);g.traverse(o=>{if(o.geometry)o.geometry.dispose();if(o.material){const ms=Array.isArray(o.material)?o.material:[o.material];ms.forEach(m=>{m.map?.dispose();m.dispose();});}});}
function cleanupItems(){for(const g of [...itemRoots])disposeItem(g);itemRoots.length=0;currentItem=null;}
function chooseCurrent(root){currentItem=root;itemRoots.forEach(g=>g.traverse(o=>{if(o.material?.emissive){o.material.emissive.set(g===root?0x15553b:0x000000);o.material.emissiveIntensity=g===root?.45:0;}}));const d=root?.userData.sortItem;if(d&&mode!=='campaign'){$('missionTitle').textContent=mode==='race'?`Sort it fast: ${d.name}`:d.name;$('missionSub').textContent=mode==='lesson'?lessons[lessonIndex]?.hint||d.hint:mode==='race'?`Which stream should ${d.name.toLowerCase()} go into?`:'Selected from the street — choose its correct stream.';}}
function addStreetItems(list,positions){cleanupItems();list.forEach((d,i)=>{const g=makeItemMesh(d,new THREE.Vector3(...positions[i]));g.userData.sortItem.instanceId=`${d.id}-${campaignIndex}-${i}`;});if(!['explore','coop','campaign'].includes(mode)&&itemRoots[0])chooseCurrent(itemRoots[0]);else if(['explore','coop','campaign'].includes(mode)){exploreItems=[...itemRoots];if(mode==='campaign'){const m=campaignMissions[campaignIndex];$('missionTitle').textContent=m.title;$('missionSub').textContent=m.brief;}else{$('missionTitle').textContent='Clean Greenview block';$('missionSub').textContent='Walk to litter, pick it up, and drag it to the matching stream bin.';}updateChecklist();}}
function updateChecklist(){const exploring=['explore','coop','campaign'].includes(mode),total=mode==='campaign'?campaignMissions.slice(campaignStartIndex).reduce((n,m)=>n+m.items.length,0):exploring?exploreItems.length+exploreCleaned:lessons.length,done=mode==='campaign'?correct:exploring?exploreCleaned:mode==='lesson'?lessonIndex:correct;$('checkCount').textContent=`${done} / ${total} SORTED`;$('targetList').innerHTML=(exploring?exploreItems.map(g=>g.userData.sortItem):lessons).slice(0,5).map(d=>`<span class="target-pill"><b>•</b>${d.name}</span>`).join('')||'<span class="target-pill"><b>✓</b>Block cleared</span>';}
function renderMissionSelect(){const wrap=$('missionCards');wrap.innerHTML=campaignMissions.map((m,i)=>`<button class="mission-select-card${i===selectedCampaignIndex?' selected':''}" data-mission-index="${i}"><span class="mission-number">${String(i+1).padStart(2,'0')}</span><span class="mission-info"><strong>${m.title}</strong><small>${m.objective} · ${m.district}</small></span></button>`).join('');wrap.querySelectorAll('[data-mission-index]').forEach(button=>button.addEventListener('click',()=>{selectedCampaignIndex=Number(button.dataset.missionIndex);wrap.querySelectorAll('.mission-select-card').forEach((card,i)=>card.classList.toggle('selected',i===selectedCampaignIndex));}));}
function setCampaignBeacon(){if(campaignBeacon){dynamicWorld.remove(campaignBeacon);campaignBeacon.traverse(o=>{o.geometry?.dispose();if(o.material){o.material.map?.dispose();o.material.dispose();}});}const m=campaignMissions[campaignIndex];if(!m)return;campaignBeacon=new THREE.Group();campaignBeacon.position.set(m.x,0,m.z);dynamicWorld.add(campaignBeacon);const ring=new THREE.Mesh(new THREE.TorusGeometry(4.4,.18,10,56),new THREE.MeshStandardMaterial({color:0xffca6a,emissive:0xff852f,emissiveIntensity:1.2,metalness:.25,roughness:.28}));ring.rotation.x=Math.PI/2;ring.position.y=.22;campaignBeacon.add(ring);const beam=new THREE.Mesh(new THREE.CylinderGeometry(.18,1.55,19,18,1,true),new THREE.MeshBasicMaterial({color:0xffb84d,transparent:true,opacity:.16,side:THREE.DoubleSide,depthWrite:false}));beam.position.y=9.5;campaignBeacon.add(beam);const icon=spriteLabel(`DISPATCH ${campaignIndex+1} · ${m.district.toUpperCase()}`,0xffbd5a,10);icon.position.y=21;campaignBeacon.add(icon);const light=new THREE.PointLight(0xffa94d,2,24,2);light.position.y=5;campaignBeacon.add(light);}
function startCampaignMission(){const m=campaignMissions[campaignIndex];if(!m){finish('campaign');return;}setCampaignBeacon();const positions=m.items.map((_,i)=>[m.x+[-5,4,-3,5,0,2][i%6],1.35,m.z+[3,-4,-7,7,10,-11][i%6]]);addStreetItems(m.items,positions);$('missionLabel').textContent=`CITYWIDE DISPATCH · ${campaignIndex+1} / ${campaignMissions.length} · ${m.district.toUpperCase()}`;$('missionTitle').textContent=m.title;$('missionSub').textContent=m.brief;$('gpsLine').hidden=false;updateChecklist();setCoach(`Dispatch from ${m.district}. Follow the gold beacon, vacuum or collect the street litter, then sort it at the local station.`);}
function updateGps(dt){if(mode!=='campaign'||!active||!playerRoot)return;gpsRefresh-=dt;if(gpsRefresh>0)return;gpsRefresh=.18;const m=campaignMissions[campaignIndex];if(!m)return;const dx=m.x-playerRoot.position.x,dz=m.z-playerRoot.position.z,dist=Math.hypot(dx,dz),bearing=(Math.atan2(dx,-dz)*180/Math.PI+360)%360,dirs=['N','NE','E','SE','S','SW','W','NW'],dir=dirs[Math.round(bearing/45)%8],arrow=['↑','↗','→','↘','↓','↙','←','↖'][Math.round(bearing/45)%8];$('gpsLine').innerHTML=`<span>${arrow}</span> &nbsp;${dir} ${Math.round(dist*4)} m · ${m.district.toUpperCase()}`;if(campaignBeacon)campaignBeacon.children[0].rotation.z+=dt*.45;}
function distanceXZ(a,b){return Math.hypot(a.position.x-b.position.x,a.position.z-b.position.z);}
function blockedByBuilding(x,z){return cityColliders.some(b=>Math.abs(x-b.x)<b.w/2+.55&&Math.abs(z-b.z)<b.d/2+.55);}
function nearestBin(){if(!playerRoot)return null;return binRoots.reduce((best,b)=>!best||distanceXZ(playerRoot,b)<distanceXZ(playerRoot,best)?b:best,null);}
function setCoach(text){$('coachLine').textContent=text;}
function setCoopStatus(text){const node=$('coopStatus');if(node)node.textContent=text;}
function makeRemoteActor(){if(remotePlayer)return remotePlayer;remotePlayer=assets.player?addModel(assets.player,1,27,1.9,Math.PI,dynamicWorld):createActor(1,27,0xd28d53,dynamicWorld);return remotePlayer;}
function handlePeerData(data){if(!data||typeof data!=='object')return;if(data.type==='start'&&onlineRole==='guest'){networked=true;startGame('coop');setCoopStatus('Connected! You and your friend are in Greenview.');}else if(data.type==='move'){const actor=makeRemoteActor();actor.visible=active;actor.position.set(data.x,0,data.z);actor.rotation.y=data.rotation||Math.PI;}else if(data.type==='sorted'){applyRemoteSort(data.id,data.stream);}}
function bindConnection(conn,role){connection=conn;onlineRole=role;conn.on('open',()=>{if(role==='host'){networked=true;startGame('coop');conn.send({type:'start'});setCoopStatus('Partner joined. Co-op cleanup started!');}else{setCoopStatus('Connected. Waiting for the host to start the city…');conn.send({type:'hello'});}});conn.on('data',handlePeerData);conn.on('close',()=>{networked=false;setCoopStatus('Your partner disconnected. You can keep cleaning solo.');if(remotePlayer)remotePlayer.visible=false;});conn.on('error',()=>setCoopStatus('Connection hiccup. Check the room code and try again.'));}
function hostCity(){if(!window.Peer){setCoopStatus('Online co-op could not load. Try the solo city modes.');return;}setCoopStatus('Opening a temporary co-op room…');$('createRoomBtn').disabled=true;peer=new Peer();peer.on('open',id=>{$('roomCode').textContent=id;$('coopShare').hidden=false;setCoopStatus('Room ready. Send this code to your friend; the city starts when they join.');});peer.on('connection',conn=>bindConnection(conn,'host'));peer.on('error',err=>{setCoopStatus(err.type==='unavailable-id'?'That room code is taken. Create another room.':'Could not connect to the co-op service. Try a solo mode.');$('createRoomBtn').disabled=false;});}
function joinCity(){const code=$('joinCode').value.trim();if(!code){setCoopStatus('Paste the room code your friend shared first.');return;}if(!window.Peer){setCoopStatus('Online co-op could not load. Try the solo city modes.');return;}setCoopStatus('Connecting to your friend…');$('joinRoomBtn').disabled=true;peer=new Peer();peer.on('open',()=>{const conn=peer.connect(code,{reliable:true});bindConnection(conn,'guest');});peer.on('error',()=>{setCoopStatus('Could not find that room. Recheck the code and try again.');$('joinRoomBtn').disabled=false;});}
function applyRemoteSort(id,stream){if(mode!=='coop'||!active)return;const root=itemRoots.find(g=>g.userData.sortItem.instanceId===id);if(!root)return;if(root===currentItem)currentItem=null;if(root===heldItem)heldItem=null;if(root===draggingItem)draggingItem=null;disposeItem(root);itemRoots.splice(itemRoots.indexOf(root),1);exploreItems=itemRoots.slice();exploreCleaned++;correct++;attempts++;score+=60;setCoach(`Your partner sorted that into ${streams[stream]?.name||'the right stream'}.`);updateChecklist();setScore();if(!itemRoots.length&&active)setTimeout(()=>finish('coop'),400);}
function interact(){if(!active||paused||!playerRoot)return;if(heldItem){const bin=nearestBin();if(bin&&distanceXZ(playerRoot,bin)<5.2){classify(bin.userData.binKey);return;}setCoach('Carry the item to a colored bin station. Or drag it to a stream button below.');return;}const near=itemRoots.reduce((best,g)=>!best||distanceXZ(playerRoot,g)<distanceXZ(playerRoot,best)?g:best,null);if(near&&distanceXZ(playerRoot,near)<4.5){heldItem=near;chooseCurrent(near);setCoach(`Picked up ${near.userData.sortItem.name}. Press E at a nearby bin or drag it to the matching stream.`);}else setCoach('Walk close to a highlighted piece of litter, then press E to pick it up.');}
